def stream_rows(resource, transform):
    failed = False
    try:
        while True:
            row = resource.read_next()
            if row is None:
                break
            yield transform(row)
    except GeneratorExit:
        raise
    except BaseException:
        failed = True
        raise
    finally:
        try:
            resource.close()
        except BaseException:
            if not failed:
                raise

